function ocenPogode(temperatura) {
  if (temperatura < 10) {
    return "zimno";
  } else if (temperatura < 25) {
    return "przyjemnie";
  } else {
    return "goraco";
  }
}

console.log(ocenPogode(5));  // "zimno"
console.log(ocenPogode(20)); // "przyjemnie"
console.log(ocenPogode(30)); // "goraco"

function czyPelnoletni(wiek) {
  if (wiek >= 18) {
    return true;
  } else {
    return false;
  }
}

console.log(czyPelnoletni(20)); // true
console.log(czyPelnoletni(15)); // false

function sprawdzHaslo(haslo) {
  if (haslo.length < 8) {
    return "za krotkie";
  }
  return "OK";
}

console.log(sprawdzHaslo("abc"));         // "za krotkie"
console.log(sprawdzHaslo("bezpieczneHaslo")); // "OK"

function znakLiczby(n) {
  if (n > 0) {
    return "dodatnia";
  } else if (n < 0) {
    return "ujemna";
  } else {
    return "zero";
  }
}

console.log(znakLiczby(5));  // "dodatnia"
console.log(znakLiczby(-3)); // "ujemna"
console.log(znakLiczby(0));  // "zero"

function czyPelnoletni(wiek) {
